def _ntss_midpoint_er_coeff_low_rank_factors_hook(
    unpack_flat,
    vector_field: Callable,
    species: Any,
):
    """Return an analytic Er-coefficient low-rank factor hook when available.

    For the NTSS-like midpoint permittivity model, the fixed-flux Er RHS depends
    on all densities only through one midpoint scalar ``ni_mid``. That makes the
    nonlocal part of the Radau stage transpose a low-rank correction with rank
    bounded by the number of Radau stages.
    """
    owner = getattr(vector_field, "__self__", None)
    if owner is None or not hasattr(owner, "_resolve_equations"):
        return None
    if not hasattr(owner, "_prepare_working_state") or not hasattr(owner, "_shared_flux_bc_kwargs"):
        return None
    shared_flux_model = getattr(owner, "shared_flux_model", None)
    if shared_flux_model is None or not hasattr(shared_flux_model, "evaluate_with_lagged_response"):
        return None
    _density_eq, _temperature_eq, er_eq = owner._resolve_equations()
    if er_eq is None:
        return None
    mode = str(getattr(er_eq, "permitivity_mode", "")).strip().lower()
    if mode not in {"ntss_like_midpoint", "ntss_like", "ntssfusion_midpoint"}:
        return None
    density_indices_raw = getattr(er_eq, "ntss_density_indices", None)
    if density_indices_raw is None:
        return None
    density_indices = tuple(int(index) for index in np.asarray(density_indices_raw).reshape((-1,)))
    if not density_indices:
        return None

    eidx = _electron_density_index(species)
    packed_density_indices = []
    for index in density_indices:
        if eidx is not None and index == eidx:
            continue
        packed_density_indices.append(index if eidx is None or index < eidx else index - 1)
    packed_density_indices = tuple(packed_density_indices)
    if not packed_density_indices:
        return None

    def _correction_factors(
        kernel_context,
        physics_context,
        carry_in,
        primal_result,
        lagged_response,
    ):
        from ._transport_equations import _get_center_flux

        layout, radial_permutation, radial_block_dim = _radau_stage_to_radial_permutation_and_block_dim(
            kernel_context
        )
        active_er_size = int(layout.active_er_size)
        if active_er_size <= 0:
            raise ValueError("woodbury_er_coeff_compact requires active Er state variables.")

        stage_times, stage_states = _radau_exact_stage_times_states(
            kernel_context,
            carry_in,
            primal_result,
        )
        del stage_times
        n_radial = int(layout.n_radial)
        density_species_count = int(layout.density_species_count)
        if any(index < 0 or index >= density_species_count for index in packed_density_indices):
            raise ValueError(
                "woodbury_er_coeff_compact inferred packed density indices outside "
                f"the Radau density layout: packed_indices={packed_density_indices}, "
                f"density_species_count={density_species_count}."
            )
        density_end = int(kernel_context.density_size)
        pressure_end = density_end + int(kernel_context.pressure_size)
        er_start = pressure_end
        mid_index = n_radial // 2
        num_stages = int(kernel_context.num_stages)
        state_dim = int(kernel_context.state_dim)
        system_size = num_stages * state_dim
        dtype = kernel_context.dtype

        packed_density_indices_arr = jnp.asarray(packed_density_indices, dtype=jnp.int32)
        full_density_indices_arr = jnp.asarray(density_indices, dtype=jnp.int32)

        def _stage_er_coeff_profile(y_eval):
            state_y = physics_context.unpack_flat(y_eval)
            working_state, _eidx = owner._prepare_working_state(state_y)
            flux_response = (
                lagged_response.flux_response
                if hasattr(lagged_response, "flux_response")
                else lagged_response
            )
            shared_fluxes = shared_flux_model.evaluate_with_lagged_response(
                working_state,
                flux_response,
                **owner._shared_flux_bc_kwargs(),
            )
            gamma = _get_center_flux(shared_fluxes, "Gamma")
            charge_flux = er_eq._charge_flux_from_gamma(gamma)
            if str(getattr(er_eq, "boundary_mode", "")).strip().lower() == "floating_ambipolar_edge":
                charge_flux = charge_flux.at[-1].set(er_eq._charge_flux_faces_from_gamma(gamma)[-1])

            ni_raw = jnp.sum(working_state.density[full_density_indices_arr, mid_index])
            ni_floor = jnp.asarray(1.0e-30, dtype=dtype)
            ni_active = ni_raw > ni_floor
            ni_mid = jnp.maximum(ni_raw, ni_floor)
            prefactor = (
                jnp.where(ni_active, jnp.asarray(1.0, dtype=dtype), jnp.asarray(0.0, dtype=dtype))
                *
                jnp.asarray(getattr(er_eq, "Er_relax", 1.0), dtype=dtype)
                * jnp.asarray(95780.0, dtype=dtype)
                * jnp.asarray(getattr(er_eq, "ntss_B0_mid", 0.0), dtype=dtype) ** 2
                / (
                    ni_mid ** 2
                    * jnp.asarray(getattr(er_eq, "ntss_psfactor_mid", 1.0), dtype=dtype)
                )
                * jnp.asarray(1.0e-20, dtype=dtype)
            )
            return prefactor * charge_flux

        # Shape: (source_stage, er_radial_cell).
        er_coeff_profiles = jax.vmap(_stage_er_coeff_profile)(stage_states)

        u_stage = jnp.zeros((system_size, num_stages), dtype=dtype)
        v_stage = jnp.zeros((system_size, num_stages), dtype=dtype)
        stage_ids = jnp.arange(num_stages, dtype=jnp.int32)
        radial_ids = jnp.arange(n_radial, dtype=jnp.int32)

        def _fill_rank_column(carry, source_stage):
            u_acc, v_acc = carry
            row_stages = stage_ids
            row_species = packed_density_indices_arr
            row_positions = (
                row_stages[:, None, None] * jnp.asarray(state_dim, dtype=jnp.int32)
                + row_species[None, :, None] * jnp.asarray(n_radial, dtype=jnp.int32)
                + jnp.asarray(mid_index, dtype=jnp.int32)
            ).reshape((-1,))
            row_values = (
                -primal_result.trial_dt
                * kernel_context.a[source_stage, row_stages][:, None]
                * jnp.ones((num_stages, int(packed_density_indices_arr.shape[0])), dtype=dtype)
            ).reshape((-1,))
            u_acc = u_acc.at[row_positions, source_stage].set(row_values)

            er_positions = (
                source_stage * jnp.asarray(state_dim, dtype=jnp.int32)
                + jnp.asarray(er_start, dtype=jnp.int32)
                + radial_ids
            )
            v_acc = v_acc.at[er_positions, source_stage].set(er_coeff_profiles[source_stage])
            return (u_acc, v_acc), None

        (u_stage, v_stage), _ = jax.lax.scan(
            _fill_rank_column,
            (u_stage, v_stage),
            jnp.arange(num_stages, dtype=jnp.int32),
        )
        u_rank = u_stage[radial_permutation, :]
        v_rank = v_stage[radial_permutation, :]
        return radial_permutation, int(radial_block_dim), u_rank, v_rank

    def _factors(
        kernel_context,
        physics_context,
        carry_in,
        primal_result,
        lagged_response,
        *,
        rank: int,
    ):
        del rank
        (
            radial_permutation,
            radial_block_dim,
            u_rank,
            v_rank,
        ) = _correction_factors(
            kernel_context,
            physics_context,
            carry_in,
            primal_result,
            lagged_response,
        )
        (
            band_permutation,
            band_block_dim,
            block_lower,
            block_diagonal,
            block_upper,
        ) = _radau_exact_stage_transpose_radial_bands_from_matvec(
            kernel_context,
            physics_context,
            carry_in,
            primal_result,
            lagged_response,
        )
        if int(band_block_dim) != int(radial_block_dim):
            raise ValueError("Radial band builder returned an inconsistent block dimension.")
        n_radial = int(_radau_infer_radial_block_layout(kernel_context).n_radial)
        num_stages = int(kernel_context.num_stages)

        # The band builder sees the full transpose operator. Remove the analytic
        # low-rank contribution from its tridiagonal bands before adding U V.T
        # through Woodbury, otherwise the band part would be counted twice.
        def _low_rank_block(row_block, col_block):
            row_start = row_block * jnp.asarray(radial_block_dim, dtype=jnp.int32)
            col_start = col_block * jnp.asarray(radial_block_dim, dtype=jnp.int32)
            u_block = jax.lax.dynamic_slice(
                u_rank,
                (row_start, jnp.asarray(0, dtype=jnp.int32)),
                (radial_block_dim, num_stages),
            )
            v_block = jax.lax.dynamic_slice(
                v_rank,
                (col_start, jnp.asarray(0, dtype=jnp.int32)),
                (radial_block_dim, num_stages),
            )
            return u_block @ v_block.T

        block_ids = jnp.arange(n_radial, dtype=jnp.int32)
        diag_correction = jax.vmap(lambda k: _low_rank_block(k, k))(block_ids)
        zero_block = jnp.zeros_like(diag_correction[:1])
        lower_correction = jnp.concatenate(
            [
                zero_block,
                jax.vmap(lambda k: _low_rank_block(k, k - 1))(block_ids[1:]),
            ],
            axis=0,
        )
        upper_correction = jnp.concatenate(
            [
                jax.vmap(lambda k: _low_rank_block(k, k + 1))(block_ids[:-1]),
                zero_block,
            ],
            axis=0,
        )

        return (
            band_permutation,
            int(band_block_dim),
            block_lower - lower_correction,
            block_diagonal - diag_correction,
            block_upper - upper_correction,
            u_rank,
            v_rank,
        )

    # Keep the correction builder discoverable without changing the existing
    # compact-factor hook contract.  The colored dense-block experiment needs
    # only this analytic rank-3 piece, not the legacy band reconstruction.
    setattr(_factors, "ntss_midpoint_correction_factors", _correction_factors)
    return _factors


def _flat_rhs_with_lagged_response_factory(unravel, vector_field, args, kwargs, project_flat=None):
    species = _extract_species_from_args(args)
    _, eval_fn = _lagged_response_hooks(vector_field)

    def _flat_rhs(t_value, flat_y, lagged_response):
        projected_flat_y = _project_flat_state_if_needed(
            flat_y,
            project_flat,
        )
        state_y = unravel(projected_flat_y)
        if eval_fn is not None:
            rhs_tree = eval_fn(t_value, state_y, *args, lagged_response=lagged_response, **kwargs)
        else:
            rhs_tree = vector_field(t_value, state_y, *args, **kwargs)
        rhs_flat, _ = jax.flatten_util.ravel_pytree(_pack_transport_state_arrays(rhs_tree, species))
        return rhs_flat

    return _flat_rhs


def _flat_rhs_lagged_response_pullback_factory(unravel, vector_field, args, kwargs, project_flat=None):
    species = _extract_species_from_args(args)
    pullback_fn = _lagged_response_eval_pullback_hook(vector_field)
    if pullback_fn is None:
        return None
    unravel_bar = getattr(unravel, "cotangent", unravel)

    def _pullback(t_value, flat_y, lagged_response, rhs_bar_flat):
        projected_flat_y = _project_flat_state_if_needed(
            flat_y,
            project_flat,
        )
        state_y = unravel(projected_flat_y)
        rhs_bar_state = unravel_bar(jnp.asarray(rhs_bar_flat, dtype=jnp.asarray(flat_y).dtype))
        return pullback_fn(
            t_value,
            state_y,
            *args,
            lagged_response=lagged_response,
            rhs_bar=rhs_bar_state,
            **kwargs,
        )

    return _pullback


def _flat_rhs_build_support_pullback_factory(
    unravel,
    vector_field,
    args,
    kwargs,
    project_flat=None,
    reverse_segment_profile_annotations: bool = False,
):
    pullback_fn = _lagged_response_build_support_pullback_hook(vector_field)
    if pullback_fn is None:
        return None

    def _pullback(
        flat_y,
        lagged_response_bar,
        support,
        *,
        reverse_segment_profile_annotations_override: bool | None = None,
        reuse_local_vjp_primal_anchor_response: bool = False,
        support_only_ntx_implicit_pullback: bool = False,
        factorized_ntx_two_directional_prepared_vjp: bool = False,
        geometry_only_prepared_pullback: bool = False,
        geometry_implicit_ntx_two_directional_pullback: bool = False,
        reverse_rebuild_inner_timing_component: str = "full",
    ):
        projected_flat_y = _project_flat_state_if_needed(
            flat_y,
            project_flat,
        )
        state_y = unravel(projected_flat_y)
        profile_annotations = (
            bool(reverse_segment_profile_annotations)
            if reverse_segment_profile_annotations_override is None
            else bool(reverse_segment_profile_annotations_override)
        )
        pullback_kwargs = dict(kwargs)
        pullback_kwargs.update(
            reverse_segment_profile_annotations=profile_annotations,
            reuse_local_vjp_primal_anchor_response=bool(
                reuse_local_vjp_primal_anchor_response
            ),
        )
        # Preserve the existing model-hook contract in every default mode.
        # The new keyword is meaningful only for the isolated opt-in path.
        if support_only_ntx_implicit_pullback:
            pullback_kwargs["support_only_ntx_implicit_pullback"] = True
        if factorized_ntx_two_directional_prepared_vjp:
            pullback_kwargs["factorized_ntx_two_directional_prepared_vjp"] = True
        if geometry_only_prepared_pullback:
            pullback_kwargs["geometry_only_prepared_pullback"] = True
        if geometry_implicit_ntx_two_directional_pullback:
            pullback_kwargs["geometry_implicit_ntx_two_directional_pullback"] = True
        # Keep the ordinary support-pullback hook contract byte-for-byte
        # unchanged.  The selector exists only for the opt-in component timer.
        if str(reverse_rebuild_inner_timing_component).strip().lower() != "full":
            pullback_kwargs["reverse_rebuild_inner_timing_component"] = str(
                reverse_rebuild_inner_timing_component
            )
        return pullback_fn(
            state_y,
            lagged_response_bar,
            support,
            **pullback_kwargs,
        )

    return _pullback


def _flat_rhs_build_support_pullback_batched_interpolated_faces_factory(
    unravel,
    vector_field,
    args,
    kwargs,
    project_flat=None,
    reuse_local_vjp_primal: bool = False,
    multi_rhs_shared_primal: bool = False,
    native_multi_rhs_shared_primal: bool = False,
    native_multi_rhs_compact_shared_primal: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_direct_directional_product_rule: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_direct_coefficient_pullback: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_direct_directional_product_rule_per_energy_call_boundary: bool = False,
    native_multi_rhs_compact_residual_reuse_moment_drds_jvp_shared_primal: bool = False,
):
    owner = getattr(vector_field, "__self__", None)
    if native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_direct_directional_product_rule_per_energy_call_boundary:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_"
            "direct_directional_product_rule_per_energy_call_boundary"
        )
    elif native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_direct_coefficient_pullback:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_"
            "direct_coefficient_pullback"
        )
    elif native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_direct_directional_product_rule:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_"
            "direct_directional_product_rule"
        )
    elif native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients"
        )
    elif native_multi_rhs_compact_residual_reuse_moment_drds_jvp_shared_primal:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_compact_residual_reuse_moment_drds_jvp_shared_primal"
        )
    elif native_multi_rhs_reuse_moment_drds_jvp_shared_primal:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_reuse_moment_drds_jvp_shared_primal"
        )
    elif native_multi_rhs_compact_shared_primal:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_compact_shared_primal"
        )
    elif native_multi_rhs_shared_primal:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "native_multi_rhs_shared_primal"
        )
    elif multi_rhs_shared_primal:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "multi_rhs_shared_primal"
        )
    elif reuse_local_vjp_primal:
        pullback_name = (
            "pullback_build_lagged_response_support_payload_batched_interpolated_faces_"
            "reuse_local_vjp_primal"
        )
    else:
        pullback_name = "pullback_build_lagged_response_support_payload_batched_interpolated_faces"
    pullback_fn = getattr(owner, pullback_name, None)
    if pullback_fn is None:
        return None

    def _pullback(flat_y, lagged_response_bars, support):
        projected_flat_y = _project_flat_state_if_needed(flat_y, project_flat)
        state_y = unravel(projected_flat_y)
        return pullback_fn(state_y, lagged_response_bars, support, **kwargs)

    return _pullback


def _flat_rhs_build_state_and_support_pullback_batched_interpolated_faces_factory(
    unravel,
    pack_flat,
    vector_field,
    args,
    kwargs,
    project_flat=None,
    packed_support_directional_adjoint: bool = False,
    reuse_local_vjp_primal: bool = False,
    compact_prepared_support_carry: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients: bool = False,
    native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_no_prepared_carry: bool = False,
):
    """Flatten the exact joint NTX rebuild state/support pullback hook."""
    pullback_fn = _lagged_response_build_state_and_support_pullback_batched_interpolated_faces_hook(
        vector_field,
        reuse_local_vjp_primal=reuse_local_vjp_primal,
        compact_prepared_support_carry=compact_prepared_support_carry,
        native_multi_rhs_reuse_moment_drds_jvp_shared_primal=(
            native_multi_rhs_reuse_moment_drds_jvp_shared_primal
        ),
        native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients=(
            native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients
        ),
        native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_no_prepared_carry=(
            native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_no_prepared_carry
        ),
    )
    if pullback_fn is None:
        return None

    def _pullback(flat_y, lagged_response_bars, support):
        projected_flat_y = _project_flat_state_if_needed(flat_y, project_flat)
        state_y = unravel(projected_flat_y)
        pullback_result = pullback_fn(
            state_y,
            lagged_response_bars,
            support,
            packed_support_directional_adjoint=packed_support_directional_adjoint,
            **kwargs,
        )
        if (
            native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients
            or native_multi_rhs_reuse_moment_drds_jvp_shared_primal_with_vmec_coefficients_no_prepared_carry
        ):
            state_bars, support_bars, coefficient_bars = pullback_result
            return jax.vmap(pack_flat)(state_bars), support_bars, coefficient_bars
        state_bars, support_bars = pullback_result
        return jax.vmap(pack_flat)(state_bars), support_bars

    return _pullback


